/* link the tables (runs once, here): WEEKS[].ed2.pages from STOPS[].wk (STOPS order = reading order), ed2.range in words,
   WEEKS[].mcp = the MCP_WEEKS entry of the same week, MCP_WEEKS[].prepare / range from the same morning. One direction only
   (WEEKS → MCP_WEEKS), so JSON.stringify works on every table. */
(function linkWeeks() {
  const S = window.STOPS, W = window.WEEKS, M = window.MCP_WEEKS;
  W.forEach(w => { const e = w.ed2 || (w.ed2 = {});
    e.pages = S.filter(s => !s.soon && s.file && s.wk === w.wk).map(s => s.file);
    const st = e.pages.map(f => S.find(s => s.file === f).step), span = st.length ? (st.length > 1 ? `${st[0]}–${st[st.length - 1]}` : st[0]) : '';
    if (e.event) { e.label = e.range = e.title; e.label_en = e.range_en = e.en; }
    else { e.label = `บทที่ ${e.ch}${e.part ? (e.part === 1 ? ' ส่วนแรก' : ' ส่วนหลัง') : ''}`; e.label_en = `chapter ${e.ch}${e.part ? `, part ${e.part}` : ''}`;
      e.range = e.label + (span ? ` (หน้า ${span})` : e.soon ? ' (กำลังสร้าง)' : '');
      e.range_en = e.label_en + (span ? ` (${st.length > 1 ? 'pages' : 'page'} ${span})` : e.soon ? ' (in preparation)' : ''); }
    const m = M.find(x => x.wk === w.wk) || null; w.mcp = m;
    if (m) { m.prepare = e.pages.slice(); m.range = e.range; m.range_en = e.range_en; } });
  M.forEach(m => { if (!m.prepare) { m.prepare = []; m.range = m.range || ''; m.range_en = m.range_en || ''; } });
})();
